/// <summary>
/// MPJ_24248 Price Data Extract
/// </summary>
internal final class METGUPPriceComponentCodeGroupEventHanldler
{
}

Method.Source:
/// <summary>
/// Activated
/// </summary>
/// <param name="sender">Data Source</param>
/// <param name="e">event</param>
[FormDataSourceEventHandler(formDataSourceStr(GUPPriceComponentCodeGroup, GUPPriceComponentCodeGroup), FormDataSourceEventType::Activated)]
public static void GUPPriceComponentCodeGroup_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    METGUPPriceComponentCodeGroupEventHanldler::updateEditableFields(sender);
}

    /// <summary>
    /// on modified
    /// </summary>
    /// <param name="sender">Data Source field</param>
    /// <param name="e">event</param>
    [FormDataFieldEventHandler(formDataFieldStr(GUPPriceComponentCodeGroup, GUPPriceComponentCodeGroup, PriceComponent), FormDataFieldEventType::Modified)]
    public static void PriceComponent_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormDataSource  priceComponentCodeGroup_ds;

        priceComponentCodeGroup_ds = sender.datasource();

        METGUPPriceComponentCodeGroupEventHanldler::updateEditableFields(priceComponentCodeGroup_ds);
    }

    public static void updateEditableFields(FormDataSource _formDataSource)
    {
        boolean             enableCheckBox = false;
        FormCheckBoxControl promotionCheckBox;
        FormRun             formRun;
        GUPPriceComponentCodeGroup priceComponentCodeGroup;

        formRun = _formDataSource.formRun() as FormRun;
        promotionCheckBox = formRun.design(0).controlName(formControlStr(GUPPriceComponentCodeGroup, METGUPPriceComponentCodeGroup_METPromotionCode));

        priceComponentCodeGroup = _formDataSource.cursor();

        if(priceComponentCodeGroup.priceComponent == GUPPriceComponent::RetailDiscounts)
        {
            enableCheckBox = true;
        }

        promotionCheckBox.enabled(enableCheckBox);
    }
